"""Core data model: loading/saving kitty.json and all money calculations.

All money is handled as Decimal and stored as strings. Every expense is
converted to the base currency when it is recorded (using the rate in effect
at that moment), and its per-person shares are stored in the base currency,
allocated so they always add up exactly to the expense's base amount. That
keeps balances summing to exactly zero.
"""

import datetime
import json
import os
import re
import tempfile
from decimal import ROUND_DOWN, ROUND_HALF_UP, Decimal, InvalidOperation

FILENAME = "kitty.json"
CENT = Decimal("0.01")
DEFAULT_CATEGORY = "other"


class KittyError(Exception):
    """A user-facing error: printed as a message, exits with status 1."""


# ---------------------------------------------------------------- parsing


def parse_amount(text, what="amount"):
    """Parse a positive money amount with at most two decimal places."""
    try:
        value = Decimal(text.strip())
    except (InvalidOperation, AttributeError):
        raise KittyError("invalid %s: %r" % (what, text))
    if not value.is_finite():
        raise KittyError("invalid %s: %r" % (what, text))
    if value <= 0:
        raise KittyError("%s must be greater than zero: %r" % (what, text))
    if value != value.quantize(CENT):
        raise KittyError("%s can have at most two decimal places: %r" % (what, text))
    return value.quantize(CENT)


def parse_positive_number(text, what):
    """Parse a positive number of any precision (rates, shares, percentages)."""
    try:
        value = Decimal(text.strip())
    except (InvalidOperation, AttributeError):
        raise KittyError("invalid %s: %r" % (what, text))
    if not value.is_finite() or value <= 0:
        raise KittyError("%s must be a positive number: %r" % (what, text))
    return value


def parse_currency(text):
    code = text.strip().upper()
    if not re.fullmatch(r"[A-Z]{3}", code):
        raise KittyError("invalid currency code: %r (expected e.g. EUR)" % text)
    return code


def parse_date(text):
    try:
        return datetime.date.fromisoformat(text.strip()).isoformat()
    except ValueError:
        raise KittyError("invalid date: %r (expected YYYY-MM-DD)" % text)


def today():
    return datetime.date.today().isoformat()


def validate_name(name):
    name = name.strip()
    if not name:
        raise KittyError("member name cannot be empty")
    if "," in name or "=" in name:
        raise KittyError("member name cannot contain ',' or '=': %r" % name)
    if name.startswith("-"):
        raise KittyError("member name cannot start with '-': %r" % name)
    return name


def fmt(value):
    """Format a Decimal as a two-decimal string."""
    return str(Decimal(value).quantize(CENT, rounding=ROUND_HALF_UP))


def to_cents(value):
    return Decimal(value).quantize(CENT, rounding=ROUND_HALF_UP)


# ------------------------------------------------------------- allocation


def allocate(total, weights):
    """Split `total` (a cent amount) in proportion to `weights`.

    `weights` is an ordered list of (name, Decimal) pairs. Returns a dict
    name -> Decimal share, in whole cents, summing exactly to `total`.
    Everyone first gets their exact portion rounded down; the leftover
    cents then go one each to people in the order given.
    """
    weight_sum = sum(w for _, w in weights)
    total_cents = int((total / CENT).to_integral_value())
    cents = {
        name: int((Decimal(total_cents) * w / weight_sum).to_integral_value(rounding=ROUND_DOWN))
        for name, w in weights
    }
    leftover = total_cents - sum(cents.values())
    # Each person loses less than one cent to rounding down, so leftover < len(weights).
    for name, _ in weights[:leftover]:
        cents[name] += 1
    return {name: Decimal(c) * CENT for name, c in cents.items()}


# ---------------------------------------------------------------- storage


class Kitty:
    def __init__(self, data, path):
        self.data = data
        self.path = path

    # -- persistence

    @classmethod
    def create(cls, currency, directory="."):
        path = os.path.join(directory, FILENAME)
        if os.path.exists(path):
            raise KittyError("%s already exists here; not overwriting it" % FILENAME)
        data = {
            "version": 1,
            "currency": parse_currency(currency),
            "members": [],
            "rates": {},
            "expenses": [],
            "payments": [],
            "next_expense_id": 1,
            "next_payment_id": 1,
            "next_seq": 1,
        }
        kitty = cls(data, path)
        kitty.save()
        return kitty

    @classmethod
    def load(cls, directory="."):
        path = os.path.join(directory, FILENAME)
        if not os.path.exists(path):
            raise KittyError("no %s here; run 'init CURRENCY' first" % FILENAME)
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError) as e:
            raise KittyError("could not read %s: %s" % (FILENAME, e))
        if not isinstance(data, dict) or "currency" not in data:
            raise KittyError("%s is not a valid kitty file" % FILENAME)
        return cls(data, path)

    def save(self):
        # Write to a temp file and rename, so a crash never leaves a half-written file.
        directory = os.path.dirname(os.path.abspath(self.path))
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".kitty-", suffix=".json")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self.data, f, indent=2, ensure_ascii=False)
                f.write("\n")
            os.replace(tmp, self.path)
        except BaseException:
            if os.path.exists(tmp):
                os.unlink(tmp)
            raise

    # -- basics

    @property
    def currency(self):
        return self.data["currency"]

    @property
    def members(self):
        return self.data["members"]

    def _next(self, key):
        value = self.data[key]
        self.data[key] = value + 1
        return value

    def find_member(self, name):
        """Return the member's name as first added, matching case-insensitively."""
        key = name.strip().casefold()
        for member in self.members:
            if member.casefold() == key:
                return member
        return None

    def require_member(self, name):
        member = self.find_member(name)
        if member is None:
            raise KittyError("unknown member: %r" % name.strip())
        return member

    def rate_for(self, currency):
        if currency == self.currency:
            return Decimal(1)
        if currency not in self.data["rates"]:
            raise KittyError(
                "no exchange rate for %s; run 'rate set %s RATE' first" % (currency, currency)
            )
        return Decimal(self.data["rates"][currency])

    # -- members

    def add_member(self, name):
        name = validate_name(name)
        existing = self.find_member(name)
        if existing is not None:
            raise KittyError("%r is already a member (as %r)" % (name, existing))
        self.members.append(name)

    def remove_member(self, name):
        name = self.require_member(name)
        for e in self.data["expenses"]:
            if e["payer"] == name or name in e["shares"]:
                raise KittyError(
                    "%r is part of expense %d; remove it first" % (name, e["id"])
                )
        for p in self.data["payments"]:
            if name in (p["from"], p["to"]):
                raise KittyError(
                    "%r is part of payment %d; remove it first" % (name, p["id"])
                )
        self.members.remove(name)

    # -- rates

    def set_rate(self, currency, rate):
        currency = parse_currency(currency)
        if currency == self.currency:
            raise KittyError("%s is the base currency; its rate is always 1" % currency)
        self.data["rates"][currency] = str(parse_positive_number(rate, "rate"))

    # -- expenses

    def _parse_pairs(self, text, option):
        pairs = []
        for item in text.split(","):
            if "=" not in item:
                raise KittyError("%s expects NAME=VALUE,...; got %r" % (option, item))
            name, value = item.split("=", 1)
            name = self.require_member(name)
            if name in [n for n, _ in pairs]:
                raise KittyError("%r listed twice in %s" % (name, option))
            pairs.append((name, value))
        return pairs

    def _weights(self, amount, among=None, exact=None, shares=None, percent=None):
        """Return the ordered (name, weight) list describing how to split."""
        given = [o for o in (among, exact, shares, percent) if o is not None]
        if len(given) > 1:
            raise KittyError("use only one of --among, --exact, --shares, --percent")

        if exact is not None:
            weights = [(n, parse_amount(v, "exact amount for %s" % n))
                       for n, v in self._parse_pairs(exact, "--exact")]
            total = sum(w for _, w in weights)
            if total != amount:
                raise KittyError(
                    "--exact amounts add up to %s but the expense is %s" % (fmt(total), fmt(amount))
                )
            return weights
        if shares is not None:
            return [(n, parse_positive_number(v, "share for %s" % n))
                    for n, v in self._parse_pairs(shares, "--shares")]
        if percent is not None:
            weights = [(n, parse_positive_number(v, "percentage for %s" % n))
                       for n, v in self._parse_pairs(percent, "--percent")]
            total = sum(w for _, w in weights)
            if total != 100:
                raise KittyError("--percent values add up to %s, not 100" % "{:f}".format(total.normalize()))
            return weights

        if among is not None:
            names = []
            for raw in among.split(","):
                name = self.require_member(raw)
                if name in names:
                    raise KittyError("%r listed twice in --among" % name)
                names.append(name)
        else:
            names = list(self.members)
        if not names:
            raise KittyError("there is nobody to split this expense among")
        return [(n, Decimal(1)) for n in names]

    def add_expense(self, payer, amount, description, currency=None, date=None,
                    category=None, among=None, exact=None, shares=None, percent=None):
        payer = self.require_member(payer)
        amount = parse_amount(amount)
        description = description.strip()
        if not description:
            raise KittyError("description cannot be empty")
        currency = parse_currency(currency) if currency else self.currency
        date = parse_date(date) if date else today()
        category = (category or DEFAULT_CATEGORY).strip().lower()
        if not category:
            raise KittyError("category cannot be empty")

        weights = self._weights(amount, among, exact, shares, percent)
        rate = self.rate_for(currency)
        base_amount = to_cents(amount * rate)
        if base_amount <= 0:
            raise KittyError("expense is worth less than 0.01 %s" % self.currency)
        split = allocate(base_amount, weights)

        expense = {
            "id": self._next("next_expense_id"),
            "seq": self._next("next_seq"),
            "date": date,
            "payer": payer,
            "description": description,
            "amount": fmt(amount),
            "currency": currency,
            "rate": str(rate),
            "base_amount": fmt(base_amount),
            "category": category,
            "shares": {n: fmt(v) for n, v in split.items()},
        }
        self.data["expenses"].append(expense)
        return expense

    def remove_expense(self, expense_id):
        return self._remove("expenses", expense_id, "expense")

    def _remove(self, key, record_id, what):
        try:
            record_id = int(record_id)
        except ValueError:
            raise KittyError("invalid %s ID: %r" % (what, record_id))
        for i, record in enumerate(self.data[key]):
            if record["id"] == record_id:
                return self.data[key].pop(i)
        raise KittyError("no %s with ID %d" % (what, record_id))

    def list_expenses(self):
        out = []
        for e in self._sorted(self.data["expenses"]):
            out.append({
                "id": e["id"],
                "date": e["date"],
                "payer": e["payer"],
                "description": e["description"],
                "amount": e["amount"],
                "currency": e["currency"],
                "base_amount": e["base_amount"],
                "category": e["category"],
                "shares": dict(e["shares"]),
            })
        return out

    # -- payments

    def add_payment(self, sender, recipient, amount, currency=None, date=None):
        sender = self.require_member(sender)
        recipient = self.require_member(recipient)
        if sender == recipient:
            raise KittyError("a member cannot pay themselves")
        amount = parse_amount(amount)
        currency = parse_currency(currency) if currency else self.currency
        date = parse_date(date) if date else today()
        rate = self.rate_for(currency)
        base_amount = to_cents(amount * rate)
        if base_amount <= 0:
            raise KittyError("payment is worth less than 0.01 %s" % self.currency)
        payment = {
            "id": self._next("next_payment_id"),
            "seq": self._next("next_seq"),
            "date": date,
            "from": sender,
            "to": recipient,
            "amount": fmt(amount),
            "currency": currency,
            "rate": str(rate),
            "base_amount": fmt(base_amount),
        }
        self.data["payments"].append(payment)
        return payment

    def remove_payment(self, payment_id):
        return self._remove("payments", payment_id, "payment")

    def list_payments(self):
        return [
            {k: p[k] for k in ("id", "date", "from", "to", "amount", "currency", "base_amount")}
            for p in self._sorted(self.data["payments"])
        ]

    # -- reports

    @staticmethod
    def _sorted(records):
        return sorted(records, key=lambda r: (r["date"], r["seq"]))

    def balance_values(self):
        balances = {m: Decimal(0) for m in self.members}
        for e in self.data["expenses"]:
            balances[e["payer"]] += Decimal(e["base_amount"])
            for name, share in e["shares"].items():
                balances[name] -= Decimal(share)
        for p in self.data["payments"]:
            balances[p["from"]] += Decimal(p["base_amount"])
            balances[p["to"]] -= Decimal(p["base_amount"])
        return balances

    def balances(self):
        return {m: fmt(v) for m, v in self.balance_values().items()}

    def settle(self):
        """Suggest payments that square everyone up.

        Greedy: repeatedly have the person who owes most pay the person owed
        most. This needs at most (number of people - 1) payments. Ties go to
        whoever comes first alphabetically, ignoring case.
        """
        balances = self.balance_values()
        debtors = {m: -v for m, v in balances.items() if v < 0}
        creditors = {m: v for m, v in balances.items() if v > 0}
        transfers = []
        while debtors and creditors:
            debtor = min(debtors, key=lambda m: (-debtors[m], m.casefold()))
            creditor = min(creditors, key=lambda m: (-creditors[m], m.casefold()))
            amount = min(debtors[debtor], creditors[creditor])
            transfers.append({"from": debtor, "to": creditor, "amount": fmt(amount)})
            debtors[debtor] -= amount
            creditors[creditor] -= amount
            if debtors[debtor] == 0:
                del debtors[debtor]
            if creditors[creditor] == 0:
                del creditors[creditor]
        return transfers

    def history(self, name):
        name = self.require_member(name)
        events = []
        for e in self.data["expenses"]:
            if e["payer"] != name and name not in e["shares"]:
                continue
            change = Decimal(0)
            if e["payer"] == name:
                change += Decimal(e["base_amount"])
            change -= Decimal(e["shares"].get(name, "0"))
            events.append((e, e["description"], change))
        for p in self.data["payments"]:
            if p["from"] == name:
                events.append((p, "Payment to %s" % p["to"], Decimal(p["base_amount"])))
            elif p["to"] == name:
                events.append((p, "Payment from %s" % p["from"], -Decimal(p["base_amount"])))
        events.sort(key=lambda ev: (ev[0]["date"], ev[0]["seq"]))

        out = []
        balance = Decimal(0)
        for record, description, change in events:
            balance += change
            out.append({
                "date": record["date"],
                "description": description,
                "change": fmt(change),
                "balance": fmt(balance),
            })
        return out

    def report(self):
        totals = {}
        for e in self._sorted(self.data["expenses"]):
            category = totals.setdefault(e["category"], {})
            for name, share in e["shares"].items():
                category[name] = category.get(name, Decimal(0)) + Decimal(share)
        order = {m: i for i, m in enumerate(self.members)}
        return {
            cat: {n: fmt(v) for n, v in sorted(people.items(), key=lambda kv: order[kv[0]])}
            for cat, people in sorted(totals.items())
        }
"""Command-line interface: python3 -m kitty <command> ..."""

import argparse
import csv
import json
import sys

from kitty.ledger import Kitty, KittyError

EXPORT_COLUMNS = ["id", "date", "payer", "description", "amount", "currency",
                  "category", "base_amount"]


class Parser(argparse.ArgumentParser):
    """ArgumentParser that exits with status 1 (not 2) on usage errors."""

    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(1, "%s: error: %s\n" % (self.prog, message))


def build_parser():
    parser = Parser(prog="kitty", description="Track shared expenses on group trips.")
    commands = parser.add_subparsers(dest="command", metavar="COMMAND")
    commands.required = True

    p = commands.add_parser("init", help="start a new kitty in this directory")
    p.add_argument("currency", help="base currency, e.g. EUR")

    member = commands.add_parser("member", help="manage group members")
    member_cmds = member.add_subparsers(dest="action", metavar="ACTION")
    member_cmds.required = True
    member_cmds.add_parser("add", help="add a member").add_argument("name")
    member_cmds.add_parser("remove", help="remove a member").add_argument("name")
    member_cmds.add_parser("list", help="list members")

    expense = commands.add_parser("expense", help="record and manage expenses")
    expense_cmds = expense.add_subparsers(dest="action", metavar="ACTION")
    expense_cmds.required = True
    p = expense_cmds.add_parser("add", help="record an expense")
    p.add_argument("payer")
    p.add_argument("amount")
    p.add_argument("description", nargs="+")
    p.add_argument("--among", metavar="A,B", help="split equally among only these people")
    p.add_argument("--exact", metavar="A=30,B=20", help="split by exact amounts")
    p.add_argument("--shares", metavar="A=2,B=1", help="split by shares")
    p.add_argument("--percent", metavar="A=60,B=40", help="split by percentages")
    p.add_argument("--currency", help="currency paid in (default: base currency)")
    p.add_argument("--date", metavar="YYYY-MM-DD", help="date (default: today)")
    p.add_argument("--category", help="category (default: other)")
    expense_cmds.add_parser("list", help="list expenses")
    expense_cmds.add_parser("remove", help="remove an expense").add_argument("id")

    payment = commands.add_parser("payment", help="record and manage repayments")
    payment_cmds = payment.add_subparsers(dest="action", metavar="ACTION")
    payment_cmds.required = True
    p = payment_cmds.add_parser("add", help="record FROM paying TO back")
    p.add_argument("sender", metavar="from")
    p.add_argument("recipient", metavar="to")
    p.add_argument("amount")
    p.add_argument("--currency", help="currency paid in (default: base currency)")
    p.add_argument("--date", metavar="YYYY-MM-DD", help="date (default: today)")
    payment_cmds.add_parser("list", help="list payments")
    payment_cmds.add_parser("remove", help="remove a payment").add_argument("id")

    rate = commands.add_parser("rate", help="manage exchange rates")
    rate_cmds = rate.add_subparsers(dest="action", metavar="ACTION")
    rate_cmds.required = True
    p = rate_cmds.add_parser("set", help="set what one unit of CURRENCY is worth in the base currency")
    p.add_argument("currency")
    p.add_argument("rate")

    commands.add_parser("balances", help="show each person's overall balance")
    commands.add_parser("settle", help="suggest payments that square everyone up")
    commands.add_parser("history", help="show everything affecting one person").add_argument("name")
    commands.add_parser("report", help="show each person's spending per category")
    commands.add_parser("export", help="write expenses to a CSV file").add_argument("file")
    return parser


def emit(value):
    print(json.dumps(value, indent=2, ensure_ascii=False))


def export_csv(kitty, path):
    try:
        with open(path, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=EXPORT_COLUMNS, extrasaction="ignore")
            writer.writeheader()
            for expense in kitty.list_expenses():
                writer.writerow(expense)
    except OSError as e:
        raise KittyError("could not write %s: %s" % (path, e.strerror or e))


def run(args):
    if args.command == "init":
        kitty = Kitty.create(args.currency)
        print("Started a new kitty in %s" % kitty.currency)
        return

    kitty = Kitty.load()
    command = (args.command, getattr(args, "action", None))

    if command == ("member", "add"):
        kitty.add_member(args.name)
        kitty.save()
    elif command == ("member", "remove"):
        kitty.remove_member(args.name)
        kitty.save()
    elif command == ("member", "list"):
        emit(kitty.members)

    elif command == ("expense", "add"):
        expense = kitty.add_expense(
            args.payer, args.amount, " ".join(args.description),
            currency=args.currency, date=args.date, category=args.category,
            among=args.among, exact=args.exact, shares=args.shares, percent=args.percent,
        )
        kitty.save()
        print(expense["id"])
    elif command == ("expense", "list"):
        emit(kitty.list_expenses())
    elif command == ("expense", "remove"):
        kitty.remove_expense(args.id)
        kitty.save()

    elif command == ("payment", "add"):
        payment = kitty.add_payment(args.sender, args.recipient, args.amount,
                                    currency=args.currency, date=args.date)
        kitty.save()
        print(payment["id"])
    elif command == ("payment", "list"):
        emit(kitty.list_payments())
    elif command == ("payment", "remove"):
        kitty.remove_payment(args.id)
        kitty.save()

    elif command == ("rate", "set"):
        kitty.set_rate(args.currency, args.rate)
        kitty.save()

    elif args.command == "balances":
        emit(kitty.balances())
    elif args.command == "settle":
        emit(kitty.settle())
    elif args.command == "history":
        emit(kitty.history(args.name))
    elif args.command == "report":
        emit(kitty.report())
    elif args.command == "export":
        export_csv(kitty, args.file)


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        run(args)
    except KittyError as e:
        print("kitty: error: %s" % e, file=sys.stderr)
        return 1
    return 0
